; ========================================================================
; SPL.RES -- Fully Annotated Disassembly
; DeskMate 3.05, Tandy Corporation, Copyright (c) 1987, Microsoft Corp.
; Compiled with Microsoft C 5.x (1987)
; Annotated for the Bayside reverse engineering project
; ========================================================================
;
; SPL.RES is the spell checker core engine for DeskMate 3.05.
; It implements the actual dictionary search and word suggestion algorithms
; that SPELL.RES calls through INT 15h/70h. This is the largest spell
; checking module, containing the compressed dictionary access routines,
; phonetic matching, and edit-distance suggestion generation.
;
; The dictionary (DICT.SPL) uses a compressed trie/DAG structure to
; minimize disk and memory usage. SPL.RES reads dictionary pages on
; demand via INT 21h/3Fh and caches recently accessed pages in memory.
;
; Key algorithms:
;   - Trie traversal for exact word lookup
;   - Phonetic encoding (Soundex-like) for similar word suggestions
;   - Edit distance calculation for near-miss corrections
;   - User dictionary management (add/remove words)
;
; DM89 imports: INT E0h (host API), INT 6Bh (unknown)
; File I/O: INT 21h/3Fh (read), INT 21h/42h (seek)
; Memory: INT 21h/48h (alloc), INT 21h/49h (free)
;

; ========================================================================
; FUNCTION INDEX
; ========================================================================
;
; --- SPL.RES Functions ---
;
; Address          Name                              Description
; -------          ----                              -----------
; 011D:0000        spl_allocDictMemory               Allocate memory for dictionary page cache
; 011D:002B        spl_initEngine                    Initialize spell engine (open dict, alloc buffers)
; 011D:00A1        spl_shutdownEngine                Shutdown spell engine (close files, free memory)
; 011D:00FD        spl_decompressPage                Decompress dictionary page (8 recursive calls - trie expansion)
; 011D:024C        spl_openDictionary                Open DICT.SPL dictionary file
; 011D:02A0        spl_readDictPage                  Read dictionary page from file (recursive page walk)
; 011D:0373        spl_seekDictOffset                Seek to offset in dictionary file (2 callers)
; 011D:03C6        spl_lookupWordExact               Exact word lookup in dictionary trie (6 callers)
; 011D:03CE        spl_trieTraverse                  Traverse dictionary trie for word matching
; 011D:048D        spl_lookupWordPrefix              Prefix lookup in dictionary (6 callers)
; 011D:0495        spl_triePrefixWalk                Walk trie for prefix matching
; 011D:0524        spl_openUserDict                  Open user dictionary (USERDICT.SPL)
; 011D:0683        spl_readUserDict                  Read user dictionary entries into memory (3 callers)
; 011D:077F        spl_compareWords                  Compare two words (case-insensitive, 2 callers)
; 011D:0790        spl_toLowerCase                   Convert string to lowercase (recursive)
; 011D:07FF        spl_matchWord                     Match word against dictionary entry (3 callers)
; 011D:0821        spl_checkWordInDict               Check if word exists in dictionary (11 callers)
; 011D:082B        spl_searchDictTrie                Search dictionary trie for exact match (9 callers)
; 011D:0874        spl_getCharType                   Get character type/class (letter, digit, punct) - 3 callers
; 011D:087C        spl_isWordChar                    Check if character is word-constituent
; 011D:0884        spl_nextDictEntry                 Advance to next dictionary entry (18 callers - most called)
; 011D:088C        spl_addToSuggestions              Add word to suggestion list (5 callers)
; 011D:08A7        spl_addExactMatch                 Add exact match to results (5 callers)
; 011D:08C1        spl_clearSuggestions              Clear suggestion list
; 011D:0979        spl_generateSuggestions           Generate spelling suggestions (edit distance, 5 callers)
; 011D:0A04        spl_editDistance                  Calculate edit distance between words
; 011D:0ACF        spl_trySingleEdits                Try single-edit corrections (insert/delete/replace/swap)
; 011D:0C1E        spl_tryDoubleEdits                Try double-edit corrections
; 011D:0C9A        spl_tryPhoneticMatch              Try phonetic matching (Soundex-like)
; 011D:0D50        spl_phoneticallyEncode            Phonetically encode word for matching
; 011D:1554        spl_checkSpelling                 Top-level spell check function (check word, get suggestions)
; 011D:1771        spl_addToUserDict                 Add word to user dictionary
; 011D:181A        spl_removeFromUserDict            Remove word from user dictionary
; 011D:18EE        spl_getUserDictWords              Get words from user dictionary (iterate entries)
; 011D:210A        spl_saveUserDict                  Save user dictionary to disk
; 011D:2198        spl_mergeUserDict                 Merge user dictionary with main dictionary lookups
; 011D:2226        spl_checkWordWithUser             Check word against both main and user dictionaries
; 011D:23A6        spl_sortSuggestions               Sort suggestion list by relevance/distance
; 011D:2448        spl_rankSuggestion                Rank/score a single suggestion
; 011D:24CA        spl_getSuggestionAt               Get suggestion at index from list
; 011D:24F1        spl_getSuggestionCount            Get total count of suggestions
; 011D:2606        spl_int15hHandler                 INT 15h/70h handler - spell engine API entry point
; 011D:276C        spl_apiDispatch                   API dispatch for spell engine commands
;


